package ru.livingvillages;

import org.junit.jupiter.api.Test;
import ru.livingvillages.domain.*;
import ru.livingvillages.persistence.Database;
import java.util.*;
import static org.junit.jupiter.api.Assertions.*;

class AutonomousEconomyTest {
    @Test void twoHundredDaysProvideFoodWoodAndReplacementToolsWithoutAPlayer() throws Exception {var r=AutonomyData.rules();var v=AutonomyData.village();v.stock.take("STONE_HOE",4);v.residents.get(2).toolKind="STONE_HOE";v.residents.get(2).toolUses=1;var pit=AutonomyData.building(v,"stone_pit","stone_pit");pit.resourceLeft=500;AutonomyData.building(v,"kiln_house",null,"furnace");long treasury=v.treasury;for(int day=0;day<200;day++){new Simulation(r).day(v);if(day%7==0)v=Database.copy(v);}assertEquals(5,v.living());assertEquals(1,v.nutrition);assertTrue(v.produced.getOrDefault("OAK_LOG",0L)>32,"wood: "+v.produced);assertTrue(v.produced.getOrDefault("COBBLESTONE",0L)>0);assertTrue(v.crafted.getOrDefault("STONE_HOE",0L)>=1,"tools: "+v.crafted);assertTrue(v.stock.size()<v.capacity);assertEquals(treasury,v.treasury);assertTrue(v.relations.isEmpty());assertTrue(v.buildings.stream().filter(b->"stone_pit".equals(b.recipe)).findFirst().orElseThrow().resourceLeft<500);}
    @Test void woodWaitsForGrowthAndDoesNotRequireBuyingNewSeedlingsForever() throws Exception {var r=AutonomyData.rules();var v=AutonomyData.village();for(int i=0;i<2;i++)new Simulation(r).day(v);assertEquals(0,v.produced.getOrDefault("OAK_LOG",0L));new Simulation(r).day(v);assertEquals(8,v.produced.get("OAK_LOG"));assertEquals(1,v.stock.get("OAK_SAPLING"));assertEquals(0,v.buildings.stream().filter(b->b.recipe!=null && b.recipe.startsWith("grove")).findFirst().orElseThrow().treeVisual.size());}
    @Test void loadedAndOfflineSchedulesKeepTheSameStocksDurabilityAndFiniteDeposits() throws Exception {var r=AutonomyData.rules();var a=AutonomyData.village();var pit=AutonomyData.building(a,"stone_pit","stone_pit");pit.resourceLeft=32;AutonomyData.building(a,"kiln_house",null,"furnace");var b=Database.copy(a);for(int i=0;i<80;i++){new Simulation(r).elapse(a,r.dayMillis,1);for(int j=0;j<4;j++)new Simulation(r).elapse(b,r.dayMillis/4,1);b=Database.copy(b);}assertEquals(a.stock.items,b.stock.items);assertEquals(a.produced,b.produced);assertEquals(a.crafted,b.crafted);assertEquals(a.buildings.get(3).resourceLeft,b.buildings.get(3).resourceLeft);assertEquals(a.residents.getFirst().tools,b.residents.getFirst().tools);}
    @Test void onlyRealDepositProducesAndReloadDoesNotRefillIt() throws Exception {var r=AutonomyData.rules();var v=AutonomyData.village();var pit=AutonomyData.building(v,"stone_pit","stone_pit");pit.resourceLeft=1;AutonomyData.building(v,"sand_pit","sand_pit").resourceConfirmed=false;for(int i=0;i<20;i++){new Simulation(r).day(v);v=Database.copy(v);}assertEquals(8,v.produced.get("COBBLESTONE"));assertEquals(0,v.produced.getOrDefault("SAND",0L));assertEquals(0,v.buildings.stream().filter(b->"stone_pit".equals(b.recipe)).findFirst().orElseThrow().resourceLeft);}
    @Test void craftingCannotSpendBuildingEscrowOrFoodReserve() throws Exception {var r=AutonomyData.rules();var v=AutonomyData.village();v.stock.items.clear();v.stock.add("CARROT",20,v.capacity);var p=new Village.Project();p.building=v.buildings.getFirst().id;p.required.put("OAK_PLANKS",4);p.escrow.put("OAK_LOG",8);v.projects.add(p);Assembly.day(v,r);assertEquals(0,v.stock.get("OAK_PLANKS"));assertEquals(20,v.stock.get("CARROT"));assertEquals(8,p.escrow.get("OAK_LOG"));}
    @Test void oneResidentCannotCraftAndProduceTwiceOnTheSameDay() throws Exception {var r=AutonomyData.rules();var v=AutonomyData.village();v.stock.add("OAK_LOG",32,v.capacity);var project=new Village.Project();project.building=v.buildings.getFirst().id;project.required.put("OAK_PLANKS",128);v.projects.add(project);v.days=1;Assembly.day(v,r);var before=new TreeMap<>(v.crafted);assertFalse(before.isEmpty(),"worker performed a real craft");Assembly.day(v,r);assertEquals(before,v.crafted);assertTrue(v.residents.stream().filter(p->p.economicDay==v.days).count()<=r.craftWorkers);}
    @Test void furnaceNeedsActualFuelAndToolsCanBeRepairedFromWoodAndStone() throws Exception {var r=AutonomyData.rules();var v=AutonomyData.village();AutonomyData.building(v,"kiln_house",null,"furnace");v.stock.items.clear();v.stock.add("COBBLESTONE",64,v.capacity);v.stock.add("OAK_LOG",32,v.capacity);v.stock.add("CARROT",70,v.capacity);v.stock.add("RAW_IRON",4,v.capacity);var p=new Village.Project();p.building=v.buildings.getFirst().id;p.required.put("IRON_INGOT",4);v.projects.add(p);for(int i=0;i<20;i++)new Simulation(r).day(v);assertTrue(v.crafted.getOrDefault("IRON_INGOT",0L)>=4);assertTrue(v.crafted.getOrDefault("CHARCOAL",0L)>0);assertEquals(0,v.stock.get("RAW_IRON"));}
    @Test void workshopCannotConsumeTheFoodBuildingsMaintenanceReserve() throws Exception {var r=AutonomyData.rules();var v=AutonomyData.village();v.stock.items.clear();v.stock.add("COBBLESTONE",8,v.capacity);v.buildings.get(1).upkeep.put("COBBLESTONE",1);var p=new Village.Project();p.building=v.buildings.getFirst().id;p.required.put("FURNACE",1);v.projects.add(p);Assembly.day(v,r);assertEquals(0,v.stock.get("FURNACE"));assertTrue(v.stock.get("COBBLESTONE")>=1);}
    @Test void coreProjectsFinishBeforeTheNextFoundationReservesItsMaterials() throws Exception {var r=AutonomyData.rules();var v=AutonomyData.village();var p=new Village.Project();p.kind="camp_workbench";p.building=v.buildings.getFirst().id;v.projects.add(p);assertNull(Autonomy.next(v,r));p.state="COMPLETE";assertEquals("stone_pit",Autonomy.next(v,r));}
    @Test void workerLeavesExhaustedPitAndDoesNotRefillItsDeposit() throws Exception {var r=AutonomyData.rules();var v=AutonomyData.village();var empty=AutonomyData.building(v,"iron_pit","iron_pit");empty.resourceLeft=0;var fresh=AutonomyData.building(v,"iron_pit","iron_pit");fresh.resourceLeft=3;var worker=new Village.Resident();worker.role=Village.Role.ARTISAN;worker.workplace=empty.id;v.residents.add(worker);Jobs.reconcile(v,r);assertEquals(fresh.id,worker.workplace);assertEquals(0,empty.resourceLeft);}
    
}
